public String countDown(int n) {
    StringBuilder sb = new StringBuilder();
    helper(n, sb);
    return sb.toString().trim();
}
private void helper(int n, StringBuilder sb) {
    if (n < 1) return;
    sb.append(n).append(' ');
    helper(n - 1, sb);
}

code.python:
def count_down(n: int) -> str:
    if n < 1:
        return ""
    rest = count_down(n - 1)
    return f"{n} {rest}".strip()
